246	func (s *APIV1Service) fetchCurrentUser(ctx context.Context) (*store.User, error) {
247		userID := auth.GetUserID(ctx)
248		if userID == 0 {
249			return nil, nil
250		}
251		user, err := s.Store.GetUser(ctx, &store.FindUser{
252			ID: &userID,
253		})
254		if err != nil {
255			return nil, err
256		}
257		if user == nil {
258			return nil, errors.Errorf("user %d not found", userID)
259		}
260		if user.RowStatus == store.Archived {
261			return nil, nil
262		}
263		return user, nil
264	}
