266	// extractClientInfo extracts comprehensive client information from the request context.
267	//
268	// This function parses metadata from the gRPC context to extract:
269	// - User Agent: Raw user agent string for detailed parsing
270	// - IP Address: Client IP from X-Forwarded-For or X-Real-IP headers
271	// - Device Type: "mobile", "tablet", or "desktop" (parsed from user agent)
272	// - Operating System: OS name and version (e.g., "iOS 17.1", "Windows 10/11")
273	// - Browser: Browser name and version (e.g., "Chrome 120.0.0.0")
274	//
275	// This information enables users to:
276	// - See all active sessions with device details
277	// - Identify suspicious login attempts
278	// - Revoke specific sessions from unknown devices.
279	func (s *APIV1Service) extractClientInfo(ctx context.Context) *storepb.RefreshTokensUserSetting_ClientInfo {
280		clientInfo := &storepb.RefreshTokensUserSetting_ClientInfo{}
281	
282		// Extract user agent from metadata if available
283		if md, ok := metadata.FromIncomingContext(ctx); ok {
284			if userAgents := md.Get("user-agent"); len(userAgents) > 0 {
285				userAgent := userAgents[0]
286				clientInfo.UserAgent = userAgent
287	
288				// Parse user agent to extract device type, OS, browser info
289				s.parseUserAgent(userAgent, clientInfo)
290			}
291			if forwardedFor := md.Get("x-forwarded-for"); len(forwardedFor) > 0 {
292				ipAddress := strings.Split(forwardedFor[0], ",")[0] // Get the first IP in case of multiple
293				ipAddress = strings.TrimSpace(ipAddress)
294				clientInfo.IpAddress = ipAddress
295			} else if realIP := md.Get("x-real-ip"); len(realIP) > 0 {
296				clientInfo.IpAddress = realIP[0]
297			}
298		}
299	
300		return clientInfo
301	}
